import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { DomSanitizer } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, LoadingController, ToastController } from '@ionic/angular';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { VehicleProfile, VehicleProfileStore } from '../vehicle-profile/vehicle-profile.store';

interface RaceSample {
  distanceM: number;
  speedKmh: number;
  accelerationG: number;
  timeSeconds: number;
}

interface DragPerformanceResult {
  wheelHorsepower: number;
  powerToWeightHpPerTon: number;
  zeroTo100Seconds: number | null;
  hundredTo200Seconds: number | null;
  eighthMileSeconds: number;
  eighthMileSpeedKmh: number;
  quarterMileSeconds: number;
  quarterMileSpeedKmh: number;
  peakAccelerationG: number;
  averageAccelerationG: number;
  shiftCount: number;
}

@Component({
  selector: 'app-drag-performance',
  templateUrl: './drag-performance.component.html',
  styleUrls: ['./drag-performance.component.scss'],
})
export class DragPerformanceComponent implements OnInit {

  isShow = false;
  isCheck = true;
  profiles: VehicleProfile[] = [];
  selectedProfileId = '';
  profileNotice = '';
  private loadedProfileUpdatedAt = '';
  form: FormGroup;
  result: DragPerformanceResult | null = null;
  raceSamples: RaceSample[] = [];

  readonly chartWidth = 700;
  readonly chartHeight = 300;
  readonly chartLeft = 56;
  readonly chartRight = 24;
  readonly chartTop = 20;
  readonly chartBottom = 42;

  constructor(private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    private sanitizer: DomSanitizer,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private courseService: CourseService,
    private siteService: SliderService) {

    this.isShow = false;
    this.check();
  }

  ngOnInit(): void {
    this.form = this.fb.group({
      vehicleWeightKg: [1250, [Validators.required, Validators.min(300), Validators.max(5000)]],
      horsepower: [300, [Validators.required, Validators.min(10), Validators.max(3000)]],
      powerLocation: ['wheel', Validators.required],
      drivetrainLossPct: [15, [Validators.required, Validators.min(0), Validators.max(40)]],
      drivetrain: ['FWD', Validators.required],
      tractionCoefficient: [1.0, [Validators.required, Validators.min(0.5), Validators.max(2.0)]],
      frontalAreaCdA: [0.68, [Validators.required, Validators.min(0.2), Validators.max(2)]],
      rollingResistanceCoefficient: [0.015, [Validators.required, Validators.min(0.005), Validators.max(0.05)]],
      shiftTimeMs: [250, [Validators.required, Validators.min(0), Validators.max(1500)]],
      shiftCount: [3, [Validators.required, Validators.min(0), Validators.max(8)]],
    });
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active) { this.applyProfile(active.id); }

    this.form.valueChanges.subscribe(() => this.calculate());
    this.calculate();
  }



  ionViewWillEnter(): void {
    this.profiles = VehicleProfileStore.list();
    const active = VehicleProfileStore.active();
    if (active && this.form && (active.id !== this.selectedProfileId ||
      active.updatedAt !== this.loadedProfileUpdatedAt)) {
      this.applyProfile(active.id);
    }
  }

  applyProfile(id: string): void {
    const profile = this.profiles.find(item => item.id === id);
    if (!profile || !this.form) { return; }
    const values = VehicleProfileStore.toolValues(profile, 'drag-performance');
    let applied = 0;
    Object.keys(values).forEach(key => {
      const control = this.form.get(key);
      if (!control) { return; }
      const previous = control.value;
      control.setValue(values[key], { emitEvent: false });
      if (control.invalid) { control.setValue(previous, { emitEvent: false }); }
      else { applied++; }
    });
    const layout = String(profile.values.driveLayout || '').toLowerCase();
    const drivetrain = layout.includes('awd') || layout.includes('چهار') ? 'AWD' :
      layout.includes('rwd') || layout.includes('عقب') ? 'RWD' :
      layout.includes('fwd') || layout.includes('جلو') ? 'FWD' : '';
    if (drivetrain) { this.form.patchValue({ drivetrain }, { emitEvent: false }); }
    this.form.updateValueAndValidity();
    this.profileNotice = `${applied} مقدار از پروفایل اعمال شد؛ سایر ورودی‌ها پیش‌فرض ابزارند.`;
    this.selectedProfileId = id;
    this.loadedProfileUpdatedAt = profile.updatedAt;
    try { VehicleProfileStore.select(id); } catch { /* Local storage may be disabled. */ }
    this.calculate();
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(34).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;
                              this.isShow = true;
                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
              this.isShow = true;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  calculate(): void {
    if (this.form.invalid) {
      this.result = null;
      this.raceSamples = [];
      return;
    }

    const value = this.form.getRawValue();
    const weightKg = Number(value.vehicleWeightKg);
    const inputHorsepower = Number(value.horsepower);
    const wheelHorsepower = value.powerLocation === 'flywheel'
      ? inputHorsepower * (1 - Number(value.drivetrainLossPct) / 100)
      : inputHorsepower;
    const simulation = this.simulateRun(value, wheelHorsepower);
    this.raceSamples = simulation.samples;

    const at100 = this.timeAtSpeed(100);
    const at200 = this.timeAtSpeed(200);
    const at201 = this.sampleAtDistance(201.168);
    const at402 = this.sampleAtDistance(402.336);
    const accelerations = this.raceSamples.map(sample => sample.accelerationG).filter(valueG => valueG > 0);

    this.result = {
      wheelHorsepower: this.round(wheelHorsepower, 0),
      powerToWeightHpPerTon: this.round(wheelHorsepower / (weightKg / 1000), 1),
      zeroTo100Seconds: at100,
      hundredTo200Seconds: at100 !== null && at200 !== null ? this.round(at200 - at100, 2) : null,
      eighthMileSeconds: at201.timeSeconds,
      eighthMileSpeedKmh: at201.speedKmh,
      quarterMileSeconds: at402.timeSeconds,
      quarterMileSpeedKmh: at402.speedKmh,
      peakAccelerationG: this.round(Math.max(...accelerations), 2),
      averageAccelerationG: this.round(402.336 / Math.pow(at402.timeSeconds, 2) / 9.80665 * 2, 2),
      shiftCount: Number(value.shiftCount),
    };
  }

  get speedPath(): string {
    return this.buildPath(sample => sample.speedKmh, this.maxSpeedKmh);
  }

  get accelerationPath(): string {
    return this.buildPath(sample => sample.accelerationG, this.maxAccelerationG);
  }

  get speedTicks(): number[] {
    const maximum = this.maxSpeedKmh;
    return [0, maximum / 4, maximum / 2, maximum * 0.75, maximum].map(value => this.round(value, 0));
  }

  get accelerationTicks(): number[] {
    const maximum = this.maxAccelerationG;
    return [0, maximum / 2, maximum].map(value => this.round(value, 2));
  }

  toX(distanceM: number): number {
    return this.chartLeft + distanceM / 402.336 * this.chartPlotWidth;
  }

  toY(value: number, maximum: number): number {
    return this.chartTop + (maximum - value) / maximum * this.chartPlotHeight;
  }

  reset(): void {
    this.form.reset({
      vehicleWeightKg: 1250,
      horsepower: 300,
      powerLocation: 'wheel',
      drivetrainLossPct: 15,
      drivetrain: 'FWD',
      tractionCoefficient: 1.0,
      frontalAreaCdA: 0.68,
      rollingResistanceCoefficient: 0.015,
      shiftTimeMs: 250,
      shiftCount: 3,
    });
  }

  async onInfo(type: string): Promise<void> {
    const messages: Record<string, string> = {
      weight: 'وزن واقعی خودرو همراه راننده، سوخت و تجهیزات. این ورودی بیشترین اثر را روی زمان‌ها دارد.',
      power: 'توان اندازه‌گیری‌شده. اگر توان سر چرخ دارید WHP و اگر توان موتور دارید Flywheel HP را انتخاب کنید.',
      location: 'WHP توان ثبت‌شده روی داینو چرخ است؛ Flywheel HP توان تخمینی در میل‌لنگ پیش از افت انتقال نیرو است.',
      loss: 'درصد افت تقریبی گیربکس، دیفرانسیل و انتقال نیرو. فقط وقتی Flywheel HP انتخاب شده اثر دارد.',
      drivetrain: 'نوع انتقال نیرو در ظرفیت لانچ اثر دارد؛ AWD معمولاً چسبندگی اولیه بیشتری دارد.',
      traction: 'ضریب چسبندگی تایر و سطح مسیر. لاستیک خیابانی خشک معمولاً نزدیک 1 و سطح لغزنده کمتر است.',
      cda: 'ضریب Cd ضرب‌در سطح مقطع جلو برحسب متر مربع. عدد کمتر مقاومت هوای کمتری در سرعت بالا ایجاد می‌کند.',
      rolling: 'مقاومت غلتشی لاستیک. تایر کم‌باد یا چسبنده مقدار بیشتری دارد.',
      shiftTime: 'مدت قطع نیرو در هر تعویض دنده، برحسب میلی‌ثانیه.',
      shifts: 'تعداد تعویض‌های مورد انتظار تا پایان ۴۰۲ متر.',
    };
    await this.presentInfo(messages[type] || 'توضیحی برای این پارامتر موجود نیست.');
  }

  private async presentInfo(message: string): Promise<void> {
    const alert = await this.alertController.create({ cssClass: 'main-alert', header: 'توضیحات', message, buttons: ['بستن'] });
    await alert.present();
  }

  private simulateRun(value: Record<string, any>, wheelHorsepower: number): { samples: RaceSample[] } {
    const dt = 0.025;
    const weightKg = Number(value.vehicleWeightKg);
    const effectiveMassKg = weightKg * 1.06;
    const wheelPowerW = wheelHorsepower * 745.7;
    const tractionLimitN = Number(value.tractionCoefficient) * weightKg * 9.80665 * this.drivetrainTractionShare(value.drivetrain);
    const cda = Number(value.frontalAreaCdA);
    const rollingResistance = Number(value.rollingResistanceCoefficient) * weightKg * 9.80665;
    const shiftDuration = Number(value.shiftTimeMs) / 1000;
    const requestedShifts = Number(value.shiftCount);
    const shiftSpeedsMps = Array.from({ length: requestedShifts }, (_, index) => (45 + index * 42) / 3.6);

    const samples: RaceSample[] = [];
    let time = 0;
    let distance = 0;
    let speedMps = 0;
    let shiftRemaining = 0;
    let nextShiftIndex = 0;
    let lastSampleDistance = -5;

    while (distance < 402.336 && time < 90) {
      if (nextShiftIndex < shiftSpeedsMps.length && speedMps >= shiftSpeedsMps[nextShiftIndex]) {
        shiftRemaining = shiftDuration;
        nextShiftIndex++;
      }

      const speedKmh = speedMps * 3.6;
      const aeroDragN = 0.5 * 1.225 * cda * Math.pow(speedMps, 2);
      const powerAvailability = 0.66 + 0.34 * Math.min(1, speedKmh / 55);
      const driveForceN = shiftRemaining > 0
        ? 0
        : Math.min(tractionLimitN, wheelPowerW * powerAvailability / Math.max(speedMps, 3));
      const netForceN = Math.max(0, driveForceN - aeroDragN - rollingResistance);
      const accelerationMps2 = netForceN / effectiveMassKg;

      speedMps += accelerationMps2 * dt;
      distance += speedMps * dt;
      time += dt;
      shiftRemaining = Math.max(0, shiftRemaining - dt);

      if (distance - lastSampleDistance >= 2 || distance >= 402.336) {
        samples.push({
          distanceM: Math.min(distance, 402.336),
          speedKmh: this.round(speedMps * 3.6, 1),
          accelerationG: this.round(accelerationMps2 / 9.80665, 3),
          timeSeconds: this.round(time, 3),
        });
        lastSampleDistance = distance;
      }
    }

    return { samples };
  }

  private sampleAtDistance(distanceM: number): RaceSample {
    return this.raceSamples.find(sample => sample.distanceM >= distanceM) ?? this.raceSamples[this.raceSamples.length - 1];
  }

  private timeAtSpeed(speedKmh: number): number | null {
    const sample = this.raceSamples.find(item => item.speedKmh >= speedKmh);
    return sample ? sample.timeSeconds : null;
  }

  private buildPath(accessor: (sample: RaceSample) => number, maximum: number): string {
    return this.raceSamples
      .map((sample, index) => `${index === 0 ? 'M' : 'L'} ${this.toX(sample.distanceM)} ${this.toY(accessor(sample), maximum)}`)
      .join(' ');
  }

  private drivetrainTractionShare(drivetrain: string): number {
    const shares: Record<string, number> = { FWD: 0.58, RWD: 0.68, AWD: 1.0 };
    return shares[drivetrain] ?? shares.FWD;
  }

  get chartPlotWidth(): number { return this.chartWidth - this.chartLeft - this.chartRight; }
  get chartPlotHeight(): number { return this.chartHeight - this.chartTop - this.chartBottom; }
  get maxSpeedKmh(): number { return Math.max(50, Math.ceil(Math.max(...this.raceSamples.map(sample => sample.speedKmh), 0) / 20) * 20); }
  get maxAccelerationG(): number { return Math.max(0.1, Math.ceil(Math.max(...this.raceSamples.map(sample => sample.accelerationG), 0) * 10) / 10); }

  private round(value: number, decimals: number): number {
    const factor = Math.pow(10, decimals);
    return Math.round((value + Number.EPSILON) * factor) / factor;
  }
}
